 banner='''<div class="notice" id="ruta-de-programa"><b>Especialización · Ingeniería de Datos</b><p>Estas ocho unidades forman la base compartida AE + DE. Continúa con 16 unidades adicionales de plataforma, pipelines, Jobs, CI/CD y operación; cada una incluye práctica y evidencia de dominio.</p><a class="button" href="ingenieria-datos.html">Abrir la ruta de Ingeniería de Datos →</a></div>'''
 s=s[:pos]+banner+s[pos:]
 s=s.replace('<a href="#AE01">01 · Analytics engineering</a>','<a href="#AE01">01 · Analytics engineering</a><a href="ingenieria-datos.html">↳ Ingeniería de Datos · DE</a>',1)
